import json
import os
import time
import subprocess

QUEUE_FILE = "_tmp/render_queue.json"
MAX_RETRIES = 3


def load_queue():
    with open(QUEUE_FILE) as f:
        return json.load(f)


def save_queue(queue):
    with open(QUEUE_FILE, "w") as f:
        json.dump(queue, f)


def next_job(queue):
    for job in queue:
        if job["status"] == "pending":
            return job


def render(job):
    cmd = f"ffmpeg -y -i {job['input']} -vf scale=1080:1920 {job['output']}"
    return subprocess.call(cmd, shell=True)


def worker():
    while True:
        queue = load_queue()
        job = next_job(queue)
        job["status"] = "running"
        save_queue(queue)

        code = render(job)
        queue = load_queue()
        for j in queue:
            if j["id"] == job["id"]:
                if code == 0:
                    j["status"] = "done"
                else:
                    j["retries"] += 1
                    j["status"] = "pending"
        save_queue(queue)
        time.sleep(1)


if __name__ == "__main__":
    os.makedirs("_tmp", exist_ok=True)
    worker()

